import {decodePma,matchPma,pmaDifferences,pmaReview,selectPma,pmaLevels,pmaWarnings} from './pma-model.mjs';
import {workChart} from './work-charts.mjs';
import {nivel} from './level.mjs';
let pending;
export function loadPma(){
 if(!pending){const request=(async()=>{const c=new AbortController(),timer=setTimeout(()=>c.abort(),15000);try{const response=await fetch('./pma/catalog.json',{signal:c.signal});if(!response.ok)throw Error('No se pudo cargar la matriz PMA.');return decodePma(await response.json());}finally{clearTimeout(timer);}})();pending=request;request.catch(()=>{if(pending===request)pending=null;});}
 return pending;
}
const empty=v=>v===null||v===undefined||v===''?'Sin dato en Excel':String(v);
const labels={matched:'Código y nivel coincidentes',missing:'Sin código coincidente en PMA',eliminated:'Recinto eliminado en PMA', 'level-mismatch':'Código con otro nivel en PMA'};
function rawDetails(model,row,esc){
 const key=row.code.trim();return [[model.source.mainSheet,row],[model.source.referenceSheet,model.references.get(key)],[model.source.reviewSheet,model.reviews.get(key)]].map(([sheet,record])=>`<details class="pmaRaw"><summary>${esc(sheet)} · fila ${record.sourceRow}</summary><dl>${model.headers[sheet].fields.map((field,i)=>`<dt>${esc(model.headers[sheet].headers[i])}</dt><dd>${esc(empty(record[field]))}</dd>`).join('')}</dl></details>`).join('');
}
export function pmaRoomMarkup(model,room,levelId,esc){
 const match=matchPma(model,room,levelId),row=match.row;
 return `<h3>PMA de terminaciones · RevB</h3><p class="pmaMatch" data-pma-match="${match.state}">${labels[match.state]}</p>${row?`<p>${esc(row.name)} · ${esc(row.level)}<br>Superficie declarada: ${esc(empty(row.area))}<br>Asepsia de pintura PMA: ${esc(empty(row.asepsis))}</p><table class="finishes"><thead><tr><th>Campo</th><th>Plano</th><th>PMA</th></tr></thead><tbody>${['PAV','CIE','M1','M2','M3','M4'].map(field=>{const a=room.finishes?.find(f=>f.field===field)?.code??null;return `<tr class="${String(a??'').trim()!==String(row[field]??'').trim()?'pmaDifferent':''}"><td>${field}</td><td>${esc(empty(a))}</td><td>${esc(empty(row[field]))}</td></tr>`;}).join('')}</tbody></table><p>Revisión documental: Pavimentos ${esc(pmaReview(model,row,'PAV'))}; Cielos ${esc(pmaReview(model,row,'CIE'))}; Muros ${esc(pmaReview(model,row,'walls'))}.</p>${row.comments?`<p>${esc(row.comments)}</p>`:''}<p class="muted">${esc(model.source.mainSheet)} · fila ${row.sourceRow}. M1: norte; M2: oriente; M3: sur; M4: poniente (hoja CODIFICACIÓN MUROS). Las diferencias resaltadas requieren cotejo; cada fuente conserva sus valores.</p>${pmaWarnings(model,row).map(note=>`<p class="pmaWarning">${esc(note)}</p>`).join('')}${rawDetails(model,row,esc)}`:'<p>Se conserva la ficha original del plano; no se asignan atributos por semejanza del nombre.</p>'}<p class="muted">No acredita ejecución, cierre de protocolos ni validación geométrica. Revisión del nombre del archivo; fecha de emisión no determinada.</p><a href="source/${model.source.filename}" download="${esc(model.source.originalName)}">Descargar PMA original ↗</a>`;
}
export function mountPmaRoom(root,room,esc){
 if(!root)return;const load=async()=>{root.innerHTML='<p class="muted">Cargando PMA de terminaciones…</p>';try{const model=await loadPma();if(root.isConnected)root.innerHTML=pmaRoomMarkup(model,room,nivel.id,esc);}catch{if(root.isConnected){root.innerHTML='<p>No se pudo cargar PMA. Revisa la conexión o el paquete offline.</p><button type="button">Reintentar PMA</button>';root.querySelector('button').onclick=load;}}};void load();
}
const countItems=values=>{const map=new Map();for(const value of values)map.set(value,(map.get(value)||0)+1);return [...map].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'es')).map(([key,n],i)=>({key,n,color:['#356e88','#8a9eaa','#bd944e','#8d7c9f','#527f6b','#a26b68'][i%6]}));};
export async function renderPma(root,ctx){
 const esc=ctx.esc;root.innerHTML='<p>Cargando base documental PMA…</p>';
 let model;try{model=await loadPma();}catch{if(root.isConnected){root.innerHTML='<p>No se pudo abrir PMA.</p><button id="retryPma">Reintentar</button>';root.querySelector('button').onclick=()=>renderPma(root,ctx);}return;}if(!root.isConnected)return;
 const storage='atlas-pma-view-v1';let state={query:'',level:pmaLevels[nivel.id]||'',family:'CIE',status:'',changes:false,conflicts:false,visibility:'all',page:0,selected:null};
 try{const stored=JSON.parse(localStorage.getItem(storage));if(stored?.sha===model.source.sha256&&stored.floor===nivel.id)state={...state,...stored.state};}catch{}
 const save=()=>{try{localStorage.setItem(storage,JSON.stringify({sha:model.source.sha256,floor:nivel.id,state}));}catch{}};
 let roomIndex=new Map();const candidates=row=>(roomIndex.get(row.code.trim())||[]).filter(room=>matchPma(model,room,nivel.id).state==='matched');
 function draw(){
  if(!root.isConnected)return;
  roomIndex=new Map();for(const room of ctx.rooms()){const key=room.code.trim();if(!roomIndex.has(key))roomIndex.set(key,[]);roomIndex.get(key).push(room);}
  const rows=selectPma(model,{...state,state:state.status});const pages=Math.max(1,Math.ceil(rows.length/25));state.page=Math.max(0,Math.min(Number(state.page)||0,pages-1));
  const selected=rows.find(row=>row.id===state.selected),levels=[...new Set(model.main.map(row=>row.level))].sort();const statuses=[...new Set(model.main.map(row=>pmaReview(model,row,state.family)))].sort();
  const options=(values,value,first)=>`<option value="">${first}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('');
  const visible=rows.slice(state.page*25,state.page*25+25),linked=rows.filter(row=>candidates(row).length===1),different=linked.filter(row=>pmaDifferences(candidates(row)[0],row).length);
  root.innerHTML=`<div class="documentaryIntro"><h2>PMA de terminaciones · RevB</h2><p>Base documental del proyecto: ${model.main.length.toLocaleString('es-CL')} registros, incluyendo ${model.audit.eliminated} eliminados. Los estados de revisión del Excel se conservan como control documental.</p></div><div class="pmaFilters"><label>Buscar recinto o terminación<input id="pmaSearch" type="search" value="${esc(state.query)}" placeholder="Código, nombre, material, unidad…"></label><label>Nivel del Excel<select id="pmaLevel">${options(levels,state.level,'Todos los niveles')}</select></label><label>Familia revisada<select id="pmaFamily">${[['CIE','Cielos'],['PAV','Pavimentos'],['walls','Muros']].map(([v,l])=>`<option value="${v}" ${v===state.family?'selected':''}>${l}</option>`).join('')}</select></label><label>Estado de revisión<select id="pmaStatus">${options(statuses,state.status,'Todos los estados')}</select></label><label>Vigencia documental<select id="pmaVisibility">${[['all','Todos'],['active','No eliminados'],['eliminated','Eliminados']].map(([v,l])=>`<option value="${v}" ${v===state.visibility?'selected':''}>${l}</option>`).join('')}</select></label><label class="check"><input type="checkbox" id="pmaChanges" ${state.changes?'checked':''}> Sólo comparación X del Excel</label><label class="check"><input type="checkbox" id="pmaConflicts" ${state.conflicts?'checked':''}> Discrepancias de eliminación entre hojas</label><button id="pmaReset">Restablecer filtros</button></div><div class="contextStrip"><b id="pmaCount">${rows.length} de ${model.main.length} registros</b><span>${linked.length} localizables en ${esc(nivel.nombre)}</span><span>${different.length} con diferencias de códigos respecto del plano</span></div><div class="chartGrid pmaCharts">${workChart({title:'Revisión documental · '+{CIE:'Cielos',PAV:'Pavimentos',walls:'Muros'}[state.family],kind:'pie',items:countItems(rows.map(row=>pmaReview(model,row,state.family))),filter:'pma-status',emptyText:'Sin registros para estos filtros.',subtitle:'Estado guardado en la hoja de observaciones. No representa avance ejecutado.'},esc)}${workChart({title:'Registros por nivel PMA',items:countItems(rows.map(row=>row.level)),filter:'pma-level',emptyText:'Sin registros para estos filtros.'},esc)}</div><div class="tableScroll"><table class="masterTable pmaTable"><thead><tr><th>Recinto</th><th>Nivel</th><th>Superficie declarada</th><th>PAV</th><th>CIE</th><th>Asepsia pintura</th><th>Revisión ${esc(state.family)}</th><th>Plano actual</th></tr></thead><tbody>${visible.map(row=>`<tr><td><button data-pma-row="${row.sourceRow}" aria-expanded="${row.id===state.selected}">${esc(row.code)}</button><br>${esc(row.name)}${pmaWarnings(model,row).length?'<br><strong class="pmaWarning">Eliminación en conflicto</strong>':''}</td><td>${esc(row.level)}</td><td>${esc(empty(row.area))}</td><td>${esc(empty(row.PAV))}</td><td>${esc(empty(row.CIE))}</td><td>${esc(empty(row.asepsis))}</td><td>${esc(pmaReview(model,row,state.family))}</td><td>${candidates(row).length===1?`<button data-pma-locate="${row.sourceRow}">Ver en plano</button>`:row.level==='Recintos Eliminados'?'Eliminado en PMA':candidates(row).length>1?'Varias observaciones: revisar':'Sin vínculo en este plano'}</td></tr>`).join('')||'<tr><td colspan="8">Sin resultados para estos filtros.</td></tr>'}</tbody></table></div><div class="pagination"><button id="pmaPrev" ${state.page===0?'disabled':''}>Anterior</button><span id="pmaPage">Página ${state.page+1} de ${pages} · 25 por página</span><button id="pmaNext" ${state.page>=pages-1?'disabled':''}>Siguiente</button></div>${selected?`<section id="pmaRecord" class="chartCard"><h3>${esc(selected.code)} · ${esc(selected.name)}</h3>${pmaWarnings(model,selected).map(note=>`<p class="pmaWarning">${esc(note)}</p>`).join('')}${rawDetails(model,selected,esc)}</section>`:''}<details class="pmaSource"><summary>Fuente, alcance y leyendas</summary><p>${esc(model.source.originalName)} · ${esc(model.source.revision)}.<br>Fecha de emisión no determinada. ${esc(model.source.valueMode)}</p><small>SHA256 ${esc(model.source.sha256)}</small><p>Se vincula por código exacto y nivel: A-S01 → −1; A-N02 → 2. Otros edificios, niveles o eliminados conservan su registro sin asignarse al plano. Hay ${model.main.filter(row=>pmaWarnings(model,row).length).length} discrepancias entre hojas sobre eliminación: se pueden filtrar y no se resuelven automáticamente. Los rombos, geometrías y estados de protocolos conservan su fuente original. Comparación X es la del propio Excel; las diferencias con el plano se calculan aparte.</p><a href="source/${model.source.filename}" download="${esc(model.source.originalName)}">Descargar Excel original</a><details><summary>Alcance y notas de la carátula original</summary><p>La carátula lo presenta como antecedente complementario del anteproyecto. Su revisión en el nombre no determina precedencia sobre los planos.</p><pre style="white-space:pre-wrap;font-size:12px">${esc(model.source.cover?.notes)}</pre></details><details><summary>Códigos de terminación PMA</summary><table class="masterTable"><thead><tr><th>Código</th><th>EETT</th><th>Materialidad</th></tr></thead><tbody>${model.legends.filter(r=>r.sheet==='CODIGOS TERMINACIONES'&&r.cells.A!=='CODIGO HPC').map(r=>`<tr><td>${esc(r.cells.A)}</td><td>${esc(empty(r.cells.B))}</td><td>${esc(r.cells.C)}</td></tr>`).join('')}</tbody></table></details></details>`;
  for(const [id,key] of [['pmaLevel','level'],['pmaStatus','status'],['pmaVisibility','visibility']])root.querySelector('#'+id).onchange=e=>{state[key]=e.target.value;state.page=0;state.selected=null;save();draw();};
  root.querySelector('#pmaSearch').oninput=e=>{const position=e.target.selectionStart;state.query=e.target.value;state.page=0;state.selected=null;save();draw();const input=root.querySelector('#pmaSearch');input.focus();input.setSelectionRange(position,position);};
  root.querySelector('#pmaFamily').onchange=e=>{state.family=e.target.value;state.status='';state.page=0;state.selected=null;save();draw();};root.querySelector('#pmaConflicts').onchange=e=>{state.conflicts=e.target.checked;state.page=0;state.selected=null;save();draw();};root.querySelector('#pmaChanges').onchange=e=>{state.changes=e.target.checked;state.page=0;state.selected=null;save();draw();};
  root.querySelector('#pmaReset').onclick=()=>{state={query:'',level:'',family:'CIE',status:'',changes:false,conflicts:false,visibility:'all',page:0,selected:null};save();draw();};
  for(const [id,delta] of [['pmaPrev',-1],['pmaNext',1]])root.querySelector('#'+id).onclick=()=>{state.page+=delta;state.selected=null;save();draw();};
  root.querySelectorAll('[data-pma-row]').forEach(b=>b.onclick=()=>{const row=model.main.find(r=>r.sourceRow===Number(b.dataset.pmaRow));state.selected=state.selected===row.id?null:row.id;save();draw();root.querySelector('#pmaRecord')?.scrollIntoView({block:'nearest'});});
  root.querySelectorAll('[data-pma-locate]').forEach(b=>b.onclick=()=>{const row=model.main.find(r=>r.sourceRow===Number(b.dataset.pmaLocate)),matches=candidates(row);if(matches.length===1)ctx.locate(matches[0].id);});
  root.querySelectorAll('[data-work-filter]').forEach(b=>{const select=()=>{state[b.dataset.workFilter==='pma-status'?'status':'level']=b.dataset.workState;state.page=0;state.selected=null;save();draw();};b.onclick=select;if(b.tagName.toLowerCase()!=='button')b.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select();}};});
 }
 draw();
}
